SELECT 'датчик контракта ' || fact_gap($1, 'requirement-in-contract') || ': ответ неизвестен, а не «всё покрыто»' AS detail WHERE NOT fact_fresh($1, 'requirement-in-contract') UNION ALL SELECT r.id || ' — в контракте не названо и границы нет' FROM project_requirements r WHERE r.project_id = $1 AND r.kind = 'FR' AND fact_fresh($1, 'requirement-in-contract') AND NOT EXISTS (SELECT 1 FROM code_fact c WHERE c.project_id = r.project_id AND c.kind = 'requirement-in-contract' AND c.name = r.id) ORDER BY 1
